package cn.gmiya.malodylink;

import android.app.*;
import android.content.Context;
import android.os.*;
import android.text.*;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import org.json.JSONObject;
import java.util.*;
import java.util.function.*;

public final class SongPanel extends LinearLayout {
    private final SongCatalogue catalogue;private List<SongCatalogue.Song> results;private final Handler handler=new Handler(Looper.getMainLooper());private final EditText search;private final TextView count;private final BaseAdapter adapter;private final Consumer<SongCatalogue.Song> open;
    public SongPanel(Activity host,Engine engine,String query,Consumer<String> remember,BiConsumer<SongCatalogue.Song,Integer> rank,boolean chooser){super(host);setOrientation(1);setBackgroundColor(AppUi.BG);setPadding(AppUi.dp(host,chooser?0:16),AppUi.dp(host,chooser?8:16),AppUi.dp(host,chooser?0:16),0);catalogue=new SongCatalogue(engine.charts());
        addView(AppUi.text(host,chooser?"选择歌曲":"歌曲信息",chooser?18:26,AppUi.INK,true));AppUi.space(this,12);addView(AppUi.text(host,"搜索曲名、歌手或谱师",13,AppUi.MUTED,false));search=new EditText(host);search.setTextSize(16);search.setTextColor(AppUi.INK);search.setHintTextColor(AppUi.MUTED);search.setSingleLine(true);search.setHint("输入关键词");search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(100)});search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);addView(search,new LayoutParams(-1,AppUi.dp(host,52)));count=AppUi.text(host,"",12,AppUi.MUTED,false);addView(count);
        results=catalogue.search(query);open=song->{((InputMethodManager)host.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);if(chooser)rank.accept(song,song.charts.get(0).optInt("cid"));else details(host,song,rank);};
        adapter=new BaseAdapter(){public int getCount(){return results.size();}public Object getItem(int p){return results.get(p);}public long getItemId(int p){return results.get(p).sid;}public View getView(int position,View convert,ViewGroup parent){Holder h;if(convert==null){h=new Holder();LinearLayout row=new LinearLayout(host);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(AppUi.dp(host,12),AppUi.dp(host,12),AppUi.dp(host,12),AppUi.dp(host,12));h.art=new ImageView(host);h.art.setScaleType(ImageView.ScaleType.CENTER_CROP);h.art.setBackground(AppUi.background(host,0xff25465c));h.art.setClipToOutline(true);row.addView(h.art,new LayoutParams(AppUi.dp(host,68),AppUi.dp(host,68)));LinearLayout info=AppUi.column(host,0);LayoutParams ip=new LayoutParams(0,-2,1);ip.leftMargin=AppUi.dp(host,12);row.addView(info,ip);h.title=AppUi.text(host,"",16,AppUi.INK,true);h.title.setMaxLines(2);h.artist=AppUi.text(host,"",13,AppUi.MUTED,false);h.artist.setMaxLines(1);h.level=AppUi.text(host,"",12,AppUi.ACCENT,false);h.level.setMaxLines(2);info.addView(h.title);info.addView(h.artist);info.addView(h.level);convert=row;convert.setTag(h);}else h=(Holder)convert.getTag();SongCatalogue.Song song=results.get(position);h.title.setText(song.title);h.artist.setText(song.artist.isEmpty()?"歌手未提供":song.artist);StringBuilder levels=new StringBuilder();for(int i=0;i<Math.min(3,song.charts.size());i++){if(i>0)levels.append(" / ");levels.append(SongCatalogue.levelLabel(song.charts.get(i)));}if(song.charts.size()>3)levels.append(" · 共").append(song.charts.size()).append("谱面");h.level.setText(levels);h.art.setContentDescription(song.title+"曲绘");SongArtwork.load(host,h.art,song);return convert;}};
        ListView list=new ListView(host);list.setDividerHeight(AppUi.dp(host,1));list.setAdapter(adapter);list.setOnItemClickListener((p,v,index,id)->open.accept(results.get(index)));addView(list,new LayoutParams(-1,0,1));search.setText(query);count.setText(results.size()+" 首歌曲");Runnable filter=()->{results=catalogue.search(search.getText().toString());adapter.notifyDataSetChanged();count.setText(results.isEmpty()?"没有找到匹配歌曲":results.size()+" 首歌曲");};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int n){remember.accept(s.toString());handler.removeCallbacks(filter);handler.postDelayed(filter,160);}public void afterTextChanged(Editable e){}});search.setOnEditorActionListener((v,a,event)->{handler.removeCallbacks(filter);filter.run();((InputMethodManager)host.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);return true;});
    }
    private static final class Holder {ImageView art;TextView title,artist,level;}
    public static void details(Activity host,SongCatalogue.Song song,BiConsumer<SongCatalogue.Song,Integer> rank){ScrollView scroll=new ScrollView(host);LinearLayout body=AppUi.column(host,20);scroll.addView(body);ImageView art=new ImageView(host);art.setScaleType(ImageView.ScaleType.FIT_CENTER);art.setContentDescription(song.title+"曲绘");body.addView(art,new LayoutParams(-1,AppUi.dp(host,200)));SongArtwork.load(host,art,song);AppUi.space(body,12);body.addView(AppUi.text(host,song.title,22,AppUi.INK,true));body.addView(AppUi.text(host,"歌手 · "+(song.artist.isEmpty()?"未提供":song.artist),16,AppUi.MUTED,false));body.addView(AppUi.text(host,"BPM · "+(song.bpm.isEmpty()?"未提供":song.bpm),16,AppUi.MUTED,false));
        AlertDialog dialog=new AlertDialog.Builder(host).setView(scroll).setNegativeButton("关闭",null).create();body.addView(AppUi.button(host,"单曲排行榜",()->{dialog.dismiss();rank.accept(song,song.charts.get(0).optInt("cid"));}));
        for(JSONObject chart:song.charts){AppUi.space(body,16);LinearLayout card=AppUi.column(host,14);card.setBackground(AppUi.background(host,AppUi.CARD));card.addView(AppUi.text(host,SongCatalogue.levelLabel(chart)+" · "+chart.optString("version"),16,AppUi.ACCENT,true));String creator=chart.optString("creator");card.addView(AppUi.text(host,"谱师 · "+(creator.isEmpty()?"未提供":creator),14,AppUi.MUTED,false));card.addView(AppUi.button(host,"该谱面排行榜",()->{dialog.dismiss();rank.accept(song,chart.optInt("cid"));}));body.addView(card);}body.setBackgroundColor(AppUi.BG);dialog.show();}
    @Override protected void onDetachedFromWindow(){handler.removeCallbacksAndMessages(null);super.onDetachedFromWindow();}
}
